cypress_script:
describe('User Avatars', () => {
  it('should reveal profile links on hover for user 1', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').eq(0).trigger('mouseover');
    cy.get('a').contains('View profile').should('be.visible');
    cy.get('a').contains('View profile').click();
    cy.url().should('include', '/users/1');
  });

  it('should not navigate when hovering over an avatar without clicking', () => {
    cy.visit('https://the-internet.herokuapp.com/hovers');
    cy.get('div.figure').eq(0).trigger('mouseover');
    cy.url().should('eq', 'https://the-internet.herokuapp.com/hovers');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('User Avatars', () => {
  test('should reveal profile links on hover for user 1', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('div.figure:nth-of-type(1)');
    const profileLink = await page.locator('a').filter({ hasText: 'View profile' });
    await expect(profileLink).toBeVisible();
    await profileLink.click();
    await expect(page).toHaveURL(/.*\/users\/1/);
  });

  test('should not navigate when hovering over an avatar without clicking', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/hovers');
    await page.hover('div.figure:nth-of-type(1)');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/hovers');
  });
});
